-- Flag cross-vehicle duplicate engine/chassis numbers where source workbooks show separate vehicles.
-- This intentionally does NOT change or blank engine/chassis values; physical registration must determine corrections.
WITH note_map(nomor_polisi,note) AS (
  VALUES
('BM 1533 OA', 'DUPLIKASI IDENTITAS MESIN/RANGKA ANTARKENDARAAN: Data Kendaraan 07 Mei 2026.xlsx mencatat BM 1533 OA sebagai Honda Mobilio 2016, tetapi nomor mesin 2NRF754840 dan nomor rangka MHKE8FA3JJK016543 juga tercatat pada BM 1533 VP (Toyota Rush 2018). FPD September memisahkan kedua plat/model tersebut sebagai kendaraan operasional yang berbeda. Identitas dan nomor rangka tidak diubah; cocokkan BPKB/STNK fisik untuk menetapkan mesin/rangka yang benar.'),
('BM 1533 VP', 'DUPLIKASI IDENTITAS MESIN/RANGKA ANTARKENDARAAN: Data Kendaraan 07 Mei 2026.xlsx mencatat BM 1533 VP sebagai Toyota Rush 2018, tetapi nomor mesin 2NRF754840 dan nomor rangka MHKE8FA3JJK016543 juga tercatat pada BM 1533 OA (Honda Mobilio 2016). FPD September memisahkan kedua plat/model tersebut sebagai kendaraan operasional yang berbeda. Identitas dan nomor rangka tidak diubah; cocokkan BPKB/STNK fisik untuk menetapkan mesin/rangka yang benar.'),
('BM 8005 LN', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat BM 8005 LN dengan engine DJ35383 dan chassis MHKP3BA1JBK027565, sama persis dengan BM 9383 TI. FPD September sheet LIST KENDARAAN secara eksplisit mencocokkan engine/rangka tersebut ke BM 9383 TI (Daihatsu Grandmax, 2011, aset), sedangkan sheet STNK DAN KIR mencatat BM 8005 LN sebagai baris kendaraan terpisah (Daihatsu Grandmax/P.U 2015) tanpa engine/chassis. Belum ada sumber yang membuktikan identitas fisik BM 8005 LN; jangan menyalin atau mengganti VIN tanpa STNK/BPKB.'),
('BM 9383 TI', 'KONFLIK NOMOR MESIN/RANGKA ANTARKENDARAAN: FPD September sheet LIST KENDARAAN mengonfirmasi BM 9383 TI (Daihatsu Grandmax, 2011, aset) dengan engine DJ35383 dan chassis MHKP3BA1JBK027565. Nilai yang sama juga tercatat untuk BM 8005 LN di master Mei, sementara FPD STNK DAN KIR memuat BM 8005 LN sebagai kendaraan 2015 terpisah. Pertahankan identitas BM 9383 TI yang didukung FPD dan verifikasi dokumen fisik BM 8005 LN sebelum mengubah data.'),
('BM 8263 TI', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat engine ME30906 dan chassis MHKP3BA1JEK081391 untuk BM 8263 TI maupun BM 9764 TO. Keduanya dicatat sebagai Daihatsu Grandmax sewa milik Bpk. Johar Mawardi; FPD Sewa KEndaraan memuat pembayaran terpisah untuk BM 8263 TI. Tidak ada dasar untuk menggabungkan dua plat menjadi satu record atau menetapkan nomor mesin/rangka mana yang salah. Perlu verifikasi BPKB/STNK/kontrak.'),
('BM 9764 TO', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat engine ME30906 dan chassis MHKP3BA1JEK081391 untuk BM 9764 TO maupun BM 8263 TI. Keduanya dicatat sebagai Daihatsu Grandmax sewa milik Bpk. Johar Mawardi; lokasi BM 9764 TO tertulis Dumai. Tidak ada dasar untuk menggabungkan dua plat menjadi satu record atau menetapkan nomor mesin/rangka mana yang salah. Perlu verifikasi BPKB/STNK/kontrak.'),
('BM 9763 TO', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat engine ME35374 dan chassis MHKP3BA1JEK081902 untuk BM 9763 TO maupun BM 9808 TO. Namun FPD sheet Sewa KEndaraan memiliki tagihan terpisah untuk kedua plat sebagai kendaraan sewa berbeda. Nomor polisi tidak digabung dan VIN tidak diganti; verifikasi dokumen registrasi untuk menentukan mana nomor mesin/rangka yang benar.'),
('BM 9808 TO', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat engine ME35374 dan chassis MHKP3BA1JEK081902 untuk BM 9808 TO maupun BM 9763 TO. FPD sheet Sewa KEndaraan memiliki tagihan terpisah untuk kedua plat sebagai kendaraan sewa berbeda. Lokasi di master BM 9808 TO tercatat Bengkalis, BM 9763 TO tercatat Pakning. Nomor polisi tidak digabung dan VIN tidak diganti; verifikasi dokumen registrasi untuk menentukan mana nomor mesin/rangka yang benar.'),
('BM 1694 OK', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat BM 1694 OK dan BM 1827 JD sebagai Daihatsu Xenia 2020 sewa PT Gorent dengan engine 4N15UKB2434 dan chassis MMBJJKL10PH065322 yang sama. FPD Sewa KEndaraan memiliki rekam tagihan berulang khusus BM 1694 OK, tetapi tidak cukup untuk menetapkan VIN yang benar bagi kedua nomor polisi. Kedua kendaraan tetap terpisah; verifikasi STNK/BPKB dan dokumen pemilik sewa.'),
('BM 1827 JD', 'KONFLIK NOMOR MESIN/RANGKA: Data Kendaraan 07 Mei 2026.xlsx mencatat BM 1827 JD dan BM 1694 OK sebagai Daihatsu Xenia 2020 sewa PT Gorent dengan engine 4N15UKB2434 dan chassis MMBJJKL10PH065322 yang sama. FPD Sewa KEndaraan memiliki rekam tagihan berulang untuk BM 1694 OK, tetapi tidak cukup untuk menetapkan VIN yang benar bagi kedua nomor polisi. Kedua kendaraan tetap terpisah; verifikasi STNK/BPKB dan dokumen pemilik sewa.'),
('BM 1713 OX', 'KONFLIK NOMOR MESIN/RANGKA ANTARMODEL: Data Kendaraan 07 Mei 2026.xlsx memberi BM 1713 OX sebagai Honda Jazz 2016 tetapi engine 4G15L88671/chassis MHMU5TU2EFK172154 sama dengan BM 9084 TS (Mitsubishi Colt 2015). FPD September sheet LIST KENDARAAN secara eksplisit mengidentifikasi nomor tersebut sebagai Mitsubishi Colt T-120 BM 9084 TS; sheet STNK DAN KIR dan operasional tetap mencantumkan Honda Jazz BM 1713 OX. Dua kendaraan jangan digabung; kemungkinan ada penyalinan nomor mesin/rangka pada salah satu record, perlu verifikasi STNK/BPKB.'),
('BM 9084 TS', 'KONFLIK NOMOR MESIN/RANGKA ANTARMODEL: FPD September sheet LIST KENDARAAN secara eksplisit mengidentifikasi BM 9084 TS sebagai Mitsubishi Colt T-120 2015 dengan engine 4G15L88671 dan chassis MHMU5TU2EFK172154. Data Kendaraan 07 Mei 2026.xlsx memberi nomor mesin/rangka yang sama ke BM 1713 OX (Honda Jazz 2016), yang juga berulang di STNK dan data operasional FPD. Kedua kendaraan jangan digabung; periksa dokumen fisik sebelum mengubah VIN.')
)
UPDATE public.kendaraan k
SET keterangan = CASE
  WHEN coalesce(k.keterangan,'') LIKE '%' || split_part(nm.note, ':', 1) || '%'
    THEN k.keterangan
  ELSE concat_ws(' | ', NULLIF(btrim(k.keterangan), ''), nm.note)
END,
updated_at=now()
FROM note_map nm
WHERE k.nomor_polisi=nm.nomor_polisi;
